def _fetch_stock_news(code, name):
    """個股新聞：Google 新聞 RSS 以「股名 代號」搜尋近 14 天，只留標題含股名或代號者（K 線右側「個股新聞」用）。"""
    import xml.etree.ElementTree as ET
    from email.utils import parsedate_to_datetime
    name = name or _STOCK_NAMES.get(code, "")
    q = urllib.parse.quote(f"{name} {code} when:14d".strip())
    url = f"https://news.google.com/rss/search?q={q}&hl=zh-TW&gl=TW&ceid=TW:zh-Hant"
    req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
    with urllib.request.urlopen(req, timeout=10) as r:
        root = ET.fromstring(r.read())
    out, seen = [], set()
    for it in root.iter("item"):
        title = (it.findtext("title") or "").strip()
        src = (it.findtext("source") or "").strip()
        if src and title.endswith(" - " + src):
            title = title[: -len(src) - 3].strip()
        if not title or title in seen:
            continue
        if (name and name not in title) and code not in title:
            continue                                   # 標題沒提到這檔 → 不算個股新聞
        if "股市爆料同學會" in title or "今日股價" in title or "營收查詢" in title \
                or title.endswith("股份有限公司"):
            continue                                   # 論壇頁/行情頁/公司簡介頁，非新聞
        try:
            d = parsedate_to_datetime(it.findtext("pubDate")).astimezone(timezone(timedelta(hours=8)))
            ds = d.strftime("%Y-%m-%d %H:%M")
        except Exception:
            ds = ""
        seen.add(title)
        out.append({"title": title, "source": src, "url": (it.findtext("link") or "").strip(), "published_at": ds})
    out.sort(key=lambda x: x["published_at"], reverse=True)
    return {"code": code, "name": name, "items": out[:20]}


class handler(BaseHTTPRequestHandler):
    def log_message(self, format, *args): pass

    def _send_json(self, code, data, cache=None):
        self.send_response(code)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Access-Control-Allow-Origin", "*")
        self.send_header("Cache-Control", cache or "no-store")
        self.end_headers()
        self.wfile.write(json.dumps(data, ensure_ascii=False).encode("utf-8"))

    def do_OPTIONS(self):
        self.send_response(200)
        self.send_header("Access-Control-Allow-Origin", "*")
        self.send_header("Access-Control-Allow-Methods", "POST, GET, OPTIONS")
        self.send_header("Access-Control-Allow-Headers", "Content-Type")
        self.end_headers()

    def do_GET(self):
        # 領取非同步篩選結果：?job_id=xxx → 有結果回結果，沒好回 {pending:true}
        qs = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query)
        job_id = (qs.get("job_id") or [""])[0].strip()
        if job_id:
            cached = _cache_get(job_id)
            if cached is not None:
                return self._send_json(200, cached)
            return self._send_json(200, {"pending": True})
        # 輕量市場計數:只回漲跌/近漲跌停檔數(首頁 tile 用;重用抓全市場函式,不跑完整篩選)
        if (qs.get("stat") or [""])[0] == "market":
            try:
                stocks, mdate = fetch_all_stocks_latest()
                up = dn = fl = up_lim = dn_lim = 0
                for s in stocks.values():
                    c = s.get("close"); p = s.get("prev_close")
                    if c is None or not p:
                        continue
                    chg = (c / p - 1) * 100
                    if chg > 0: up += 1
                    elif chg < 0: dn += 1
                    else: fl += 1
                    if chg >= 9.5: up_lim += 1
                    elif chg <= -9.5: dn_lim += 1
                return self._send_json(200, {"date": mdate, "up": up, "down": dn, "flat": fl,
                                             "up_limit": up_lim, "down_limit": dn_lim, "total": len(stocks)})
            except Exception as e:
                return self._send_json(200, {"error": str(e)})
        # 股票代號→名稱對照（前端各視圖共用；純靜態，不查 DB）
        if (qs.get("stat") or [""])[0] == "names":
            return self._send_json(200, _STOCK_NAMES)
        if (qs.get("stat") or [""])[0] == "industries":
            # code→產業別中文（供首頁搜尋下拉顯示，如 2330→半導體）；上市為主
            try:
                return self._send_json(200, _get_industry_map())
            except Exception:
                return self._send_json(200, {})
        # 股票代號→產業別對照（今日索引「展開該產業全部上市股」用；純靜態）
        if (qs.get("stat") or [""])[0] == "industry":
            return self._send_json(200, _STOCK_INDUSTRY)
        # 今日焦點三榜（漲幅/跌幅/爆量）：頁面 _showView('focus') 用
        if (qs.get("stat") or [""])[0] == "focus":
            try:
                n = int((qs.get("n") or ["30"])[0])
            except Exception:
                n = 30
            try:
                return self._send_json(200, _fetch_focus(max(1, min(n, 50))))
            except Exception as e:
                import traceback
                return self._send_json(200, {"error": str(e), "traceback": traceback.format_exc()})
        # 漲停分析：今日漲停/跌停 + 連續天數
        if (qs.get("stat") or [""])[0] == "limitup":
            try:
                return self._send_json(200, _fetch_limitup())
            except Exception as e:
                import traceback
                return self._send_json(200, {"error": str(e), "traceback": traceback.format_exc()})
        # 產業地圖：各產業當日彙整
        if (qs.get("stat") or [""])[0] == "sectors":
            try:
                return self._send_json(200, _fetch_sectors())
            except Exception as e:
                import traceback
                return self._send_json(200, {"error": str(e), "traceback": traceback.format_exc()})
        # 題材族群熱力圖(固定分類,照合夥人):上市/上櫃各族群 成交額/漲跌/成分
        if (qs.get("stat") or [""])[0] == "themes":
            try:
                return self._send_json(200, _fetch_themes())
            except Exception as e:
                import traceback
                return self._send_json(200, {"error": str(e), "traceback": traceback.format_exc()})
        # 今日焦點『總覽』：合夥人焦點頁六大區塊一次算齊
        if (qs.get("stat") or [""])[0] == "overview":
            try:
                return self._send_json(200, _fetch_overview())
            except Exception as e:
                import traceback
                return self._send_json(200, {"error": str(e), "traceback": traceback.format_exc()})
        # 上櫃 ETF 代號→名稱（TPEx openapi，前端搜尋清單用；前端直連會被跨站擋；CDN 快取 1 天）2026-09-28
        if (qs.get("stat") or [""])[0] == "otcetf":
            try:
                req = urllib.request.Request("https://www.tpex.org.tw/openapi/v1/tpex_mainboard_daily_close_quotes",
                                             headers={"User-Agent": "Mozilla/5.0"})
                import ssl as _ssl
                ctx = _ssl.create_default_context(); ctx.check_hostname = False; ctx.verify_mode = _ssl.CERT_NONE
                rows = json.loads(urllib.request.urlopen(req, timeout=20, context=ctx).read().decode("utf-8-sig"))
                out = {str(r.get("SecuritiesCompanyCode", "")).strip(): str(r.get("CompanyName", "")).strip()
                       for r in rows if str(r.get("SecuritiesCompanyCode", "")).startswith("00")}
                return self._send_json(200, out, cache="public, s-maxage=86400, max-age=3600")
            except Exception as e:
                return self._send_json(200, {"error": str(e)})
        # 發行股數 code→股數（上市 t187ap03_L＋上櫃 mopsfin_t187ap03_O；K 圖市值＝股數×收盤用；CDN 快取 1 天）2026-09-28
        if (qs.get("stat") or [""])[0] == "shares":
            import ssl as _ssl
            ctx = _ssl.create_default_context(); ctx.check_hostname = False; ctx.verify_mode = _ssl.CERT_NONE
            out = {}
            for url, kc, ks in (("https://openapi.twse.com.tw/v1/opendata/t187ap03_L", "公司代號", "已發行普通股數或TDR原股發行股數"),
                                ("https://www.tpex.org.tw/openapi/v1/mopsfin_t187ap03_O", "SecuritiesCompanyCode", "IssueShares")):
                try:
                    req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
                    for r in json.loads(urllib.request.urlopen(req, timeout=20, context=ctx).read().decode("utf-8-sig")):
                        c, v = str(r.get(kc, "")).strip(), str(r.get(ks, "")).replace(",", "").strip()
                        if c and v.isdigit() and int(v) > 0:
                            out[c] = int(v)
                except Exception:
                    pass
            if len(out) < 500:                       # 官方被擋 → 內嵌備援（短快取，稍後再試官方）
                return self._send_json(200, _SHARES_FALLBACK, cache="public, s-maxage=3600, max-age=600")
            return self._send_json(200, out, cache="public, s-maxage=86400, max-age=3600")
        # 處置股（上市＋上櫃，即時抓官方 openapi；CDN 快取 30 分鐘）2026-09-28
        if (qs.get("stat") or [""])[0] == "disposal":
            try:
                return self._send_json(200, _fetch_disposal(), cache="public, s-maxage=1800, max-age=300")
            except Exception as e:
                return self._send_json(200, {"error": str(e)})
        # 證交所休市日（openapi holidaySchedule；名稱含「開始交易」「最後交易」者為交易日）→ 前端結算日順延用；CDN 快取 1 天 2026-09-28
        if (qs.get("stat") or [""])[0] == "holidays":
            try:
                import ssl as _ssl, re as _re
                ctx = _ssl.create_default_context(); ctx.check_hostname = False; ctx.verify_mode = _ssl.CERT_NONE
                req = urllib.request.Request("https://openapi.twse.com.tw/v1/holidaySchedule/holidaySchedule", headers={"User-Agent": "Mozilla/5.0"})
                out = []
                for r in json.loads(urllib.request.urlopen(req, timeout=20, context=ctx).read().decode("utf-8-sig")):
                    d = _re.sub(r"\D", "", str(r.get("Date", "")))
                    if len(d) >= 7 and not _re.search(r"開始交易|最後交易", str(r.get("Name", ""))):
                        out.append(f"{int(d[:-4]) + 1911}-{d[-4:-2]}-{d[-2:]}")
                return self._send_json(200, {"closed": sorted(set(out))}, cache="public, s-maxage=86400, max-age=3600")
            except Exception as e:
                return self._send_json(200, {"closed": [], "error": str(e)})
        # 個股新聞（Google 新聞 RSS，即時查、不存 DB；CDN 快取 30 分鐘）
        if (qs.get("stat") or [""])[0] == "stocknews":
            code = (qs.get("code") or [""])[0].strip()
            name = (qs.get("name") or [""])[0].strip()
            if not code.isalnum() or len(code) > 6:
                return self._send_json(400, {"error": "bad code"})
            try:
                return self._send_json(200, _fetch_stock_news(code, name), cache="public, s-maxage=1800, max-age=600")
            except Exception as e:
                return self._send_json(200, {"code": code, "items": [], "error": str(e)})
        # 題材全貌：單一題材的相關個股（上市＋上櫃，依成交值排序）
        if (qs.get("stat") or [""])[0] == "theme":
            try:
                name = (qs.get("name") or [""])[0].strip()
                return self._send_json(200, _fetch_theme(name))
            except Exception as e:
                import traceback
                return self._send_json(200, {"error": str(e), "traceback": traceback.format_exc()})
        self._send_json(200, {"status": "ok"})

    def do_POST(self):
        import traceback
        try:
            length = int(self.headers.get("Content-Length", 0))
            body = json.loads(self.rfile.read(length))
            job_id = body.pop("job_id", None)
            result = screen(body)
            # 先存暫存（即使前端因切背景斷線，結果也已保留可供領取），再回傳
            if job_id:
                try: _cache_save(job_id, result)
                except Exception: pass
            self._send_json(200, result)
        except Exception as e:
            self._send_json(500, {"error": str(e), "traceback": traceback.format_exc(), "results": []})
